import boto3, json, time

bedrock = boto3.client("bedrock-runtime", region_name="us-east-1")

def invoke_with_budget(model_id: str, system: str, user_text: str, max_out: int = 400):
    resp = bedrock.converse(
        modelId=model_id,
        system=[{"text": system}],
        messages=[{"role": "user", "content": [{"text": user_text}]}],
        inferenceConfig={"maxTokens": max_out, "temperature": 0.2, "stopSequences": ["###END"]},
    )
    usage = resp["usage"]  # inputTokens, outputTokens, totalTokens (キャッシュ利用時は追加項目あり)
    latency_ms = resp["metrics"]["latencyMs"]
    # EMF 形式で標準出力 -> CloudWatch Logs -> カスタムメトリクス化
    print(json.dumps({
        "_aws": {
            "Timestamp": int(time.time() * 1000),
            "CloudWatchMetrics": [{
                "Namespace": "GenAIApp",
                "Dimensions": [["Feature", "ModelId"]],
                "Metrics": [
                    {"Name": "InputTokens", "Unit": "Count"},
                    {"Name": "OutputTokens", "Unit": "Count"},
                    {"Name": "LatencyMs", "Unit": "Milliseconds"},
                ],
            }],
        },
        "Feature": "faq-bot", "ModelId": model_id,
        "InputTokens": usage["inputTokens"], "OutputTokens": usage["outputTokens"],
        "LatencyMs": latency_ms,
    }))
    return resp["output"]["message"]["content"][0]["text"]
